<!-- wp:wdl/lw-pr-custom-title-12 {"mainTitle":"ある一日の流れ","subTitle":"A DAY","headingLevel":2,"colorMain":"#1d4e89","colorSub":"#0f2a4a","colorMainText":"#ffffff","colorSubText":"#cddcef"} -->
<div class="wp-block-wdl-lw-pr-custom-title-12 lw-pr-custom-title-12" style="--color-main:#1d4e89;--lw-pr-custom-title-12-sub-color:#0f2a4a;--color-main-text:#ffffff;--color-sub-text:#cddcef"><h2 class="ttl"><span class="main">ある一日の流れ</span><span class="sub">A DAY</span></h2></div>
<!-- /wp:wdl/lw-pr-custom-title-12 -->
<!-- wp:wdl/lw-space-1 {"pcHeight":16,"tbHeight":16,"spHeight":12} -->
<div class="wp-block-wdl-lw-space-1 lw_space_1"><div class="pc" style="height:16px"></div><div class="tb" style="height:16px"></div><div class="sp" style="height:12px"></div></div>
<!-- /wp:wdl/lw-space-1 -->
<!-- wp:paragraph {"align":"center","style":{"color":{"text":"#333b45"},"typography":{"fontSize":"16px","lineHeight":"2"},"spacing":{"margin":{"top":"28px","bottom":"24px"}}}} -->
<p class="has-text-align-center has-text-color" style="color:#333b45;font-size:16px;line-height:2;margin-top:28px;margin-bottom:24px">入って2年目の社員の、ふつうの平日です。<span class="lw-br on_500px"></span>現場によって前後しますが、だいたいこの形で回っています。</p>
<!-- /wp:paragraph -->
<!-- wp:wdl/lw-space-1 {"pcHeight":24,"tbHeight":20,"spHeight":16} -->
<div class="wp-block-wdl-lw-space-1 lw_space_1"><div class="pc" style="height:24px"></div><div class="tb" style="height:20px"></div><div class="sp" style="height:16px"></div></div>
<!-- /wp:wdl/lw-space-1 -->
<!-- wp:wdl/lw-pr-step-8 {"stepNo":"01","bgGradient":"#1d4e89","colorNo":"#1d4e89","ulMaxWidth":1000,"fontWeightNo":"700"} -->
<div class="lw-pr-step-8"><div class="lw-step__inner" style="max-width:1000px"><div class="lw-step__li" style="border-color:#1d4e89;--step-8-bdr-pc:10px;--step-8-bdr-sp:10px"><div class="lw-step__li_no" data-lw_font_set="Murecho" style="font-weight:700;color:#1d4e89">01</div><div class="lw-step__li_in" style="--step-8-li-in-pt-pc:0.6em;--step-8-li-in-pt-sp:0.6em"><!-- wp:heading {"level":3,"style":{"color":{"text":"#0f2a4a"},"typography":{"fontSize":"20px","lineHeight":"1.6"},"spacing":{"margin":{"top":"0px","bottom":"16px"}}},"textAlign":"left"} -->
<h3 class="has-text-align-left has-text-color" style="color:#0f2a4a;font-size:20px;line-height:1.6;margin-top:0px;margin-bottom:16px">7:40　事務所に集合</h3>
<!-- /wp:heading -->
<!-- wp:paragraph {"style":{"color":{"text":"#333b45"},"typography":{"fontSize":"16px","lineHeight":"1.9"}}} -->
<p class="has-text-color" style="color:#333b45;font-size:16px;line-height:1.9">前の日に積んだ材料を確認して、その日の現場へ向かいます。車は先輩が運転します。移動中に、その日やることを口で確認します。</p>
<!-- /wp:paragraph --></div></div></div></div>
<!-- /wp:wdl/lw-pr-step-8 -->
<!-- wp:wdl/lw-pr-step-8 {"stepNo":"02","bgGradient":"#1d4e89","colorNo":"#1d4e89","ulMaxWidth":1000,"fontWeightNo":"700"} -->
<div class="lw-pr-step-8"><div class="lw-step__inner" style="max-width:1000px"><div class="lw-step__li" style="border-color:#1d4e89;--step-8-bdr-pc:10px;--step-8-bdr-sp:10px"><div class="lw-step__li_no" data-lw_font_set="Murecho" style="font-weight:700;color:#1d4e89">02</div><div class="lw-step__li_in" style="--step-8-li-in-pt-pc:0.6em;--step-8-li-in-pt-sp:0.6em"><!-- wp:heading {"level":3,"style":{"color":{"text":"#0f2a4a"},"typography":{"fontSize":"20px","lineHeight":"1.6"},"spacing":{"margin":{"top":"0px","bottom":"16px"}}},"textAlign":"left"} -->
<h3 class="has-text-align-left has-text-color" style="color:#0f2a4a;font-size:20px;line-height:1.6;margin-top:0px;margin-bottom:16px">8:30　現場に入る</h3>
<!-- /wp:heading -->
<!-- wp:paragraph {"style":{"color":{"text":"#333b45"},"typography":{"fontSize":"16px","lineHeight":"1.9"}}} -->
<p class="has-text-color" style="color:#333b45;font-size:16px;line-height:1.9">まず片づけと養生から。ここを丁寧にやるかどうかで、一日の進み方も、お客様の見る目も変わります。はじめの3か月はここを覚えるのが仕事です。</p>
<!-- /wp:paragraph --></div></div></div></div>
<!-- /wp:wdl/lw-pr-step-8 -->
<!-- wp:wdl/lw-pr-step-8 {"stepNo":"03","bgGradient":"#1d4e89","colorNo":"#1d4e89","ulMaxWidth":1000,"fontWeightNo":"700"} -->
<div class="lw-pr-step-8"><div class="lw-step__inner" style="max-width:1000px"><div class="lw-step__li" style="border-color:#1d4e89;--step-8-bdr-pc:10px;--step-8-bdr-sp:10px"><div class="lw-step__li_no" data-lw_font_set="Murecho" style="font-weight:700;color:#1d4e89">03</div><div class="lw-step__li_in" style="--step-8-li-in-pt-pc:0.6em;--step-8-li-in-pt-sp:0.6em"><!-- wp:heading {"level":3,"style":{"color":{"text":"#0f2a4a"},"typography":{"fontSize":"20px","lineHeight":"1.6"},"spacing":{"margin":{"top":"0px","bottom":"16px"}}},"textAlign":"left"} -->
<h3 class="has-text-align-left has-text-color" style="color:#0f2a4a;font-size:20px;line-height:1.6;margin-top:0px;margin-bottom:16px">12:00　お昼</h3>
<!-- /wp:heading -->
<!-- wp:paragraph {"style":{"color":{"text":"#333b45"},"typography":{"fontSize":"16px","lineHeight":"1.9"}}} -->
<p class="has-text-color" style="color:#333b45;font-size:16px;line-height:1.9">現場の近くで食べます。近所に食べるところが無い日は、朝のうちに買っておきます。1時間しっかり休みます。</p>
<!-- /wp:paragraph --></div></div></div></div>
<!-- /wp:wdl/lw-pr-step-8 -->
<!-- wp:wdl/lw-pr-step-8 {"stepNo":"04","bgGradient":"#1d4e89","colorNo":"#1d4e89","ulMaxWidth":1000,"fontWeightNo":"700"} -->
<div class="lw-pr-step-8"><div class="lw-step__inner" style="max-width:1000px"><div class="lw-step__li" style="border-color:#1d4e89;--step-8-bdr-pc:10px;--step-8-bdr-sp:10px"><div class="lw-step__li_no" data-lw_font_set="Murecho" style="font-weight:700;color:#1d4e89">04</div><div class="lw-step__li_in" style="--step-8-li-in-pt-pc:0.6em;--step-8-li-in-pt-sp:0.6em"><!-- wp:heading {"level":3,"style":{"color":{"text":"#0f2a4a"},"typography":{"fontSize":"20px","lineHeight":"1.6"},"spacing":{"margin":{"top":"0px","bottom":"16px"}}},"textAlign":"left"} -->
<h3 class="has-text-align-left has-text-color" style="color:#0f2a4a;font-size:20px;line-height:1.6;margin-top:0px;margin-bottom:16px">13:00　午後の作業</h3>
<!-- /wp:heading -->
<!-- wp:paragraph {"style":{"color":{"text":"#333b45"},"typography":{"fontSize":"16px","lineHeight":"1.9"}}} -->
<p class="has-text-color" style="color:#333b45;font-size:16px;line-height:1.9">午前の続きです。手が空いたら道具の手入れをします。分からないことはその場で聞いてください。聞かずに進めて直すほうが、ずっと時間がかかります。</p>
<!-- /wp:paragraph --></div></div></div></div>
<!-- /wp:wdl/lw-pr-step-8 -->
<!-- wp:wdl/lw-pr-step-8 {"stepNo":"05","bgGradient":"#1d4e89","colorNo":"#1d4e89","ulMaxWidth":1000,"fontWeightNo":"700"} -->
<div class="lw-pr-step-8"><div class="lw-step__inner" style="max-width:1000px"><div class="lw-step__li" style="border-color:#1d4e89;--step-8-bdr-pc:10px;--step-8-bdr-sp:10px"><div class="lw-step__li_no" data-lw_font_set="Murecho" style="font-weight:700;color:#1d4e89">05</div><div class="lw-step__li_in" style="--step-8-li-in-pt-pc:0.6em;--step-8-li-in-pt-sp:0.6em"><!-- wp:heading {"level":3,"style":{"color":{"text":"#0f2a4a"},"typography":{"fontSize":"20px","lineHeight":"1.6"},"spacing":{"margin":{"top":"0px","bottom":"16px"}}},"textAlign":"left"} -->
<h3 class="has-text-align-left has-text-color" style="color:#0f2a4a;font-size:20px;line-height:1.6;margin-top:0px;margin-bottom:16px">17:00　片づけて戻る</h3>
<!-- /wp:heading -->
<!-- wp:paragraph {"style":{"color":{"text":"#333b45"},"typography":{"fontSize":"16px","lineHeight":"1.9"}}} -->
<p class="has-text-color" style="color:#333b45;font-size:16px;line-height:1.9">現場をきれいにして事務所へ。道具を戻して、明日の材料を積んだら終わりです。残業は月に5時間ほどです。</p>
<!-- /wp:paragraph --></div></div></div></div>
<!-- /wp:wdl/lw-pr-step-8 -->
<!-- wp:wdl/lw-space-1 {"pcHeight":80,"tbHeight":64,"spHeight":40} -->
<div class="wp-block-wdl-lw-space-1 lw_space_1"><div class="pc" style="height:80px"></div><div class="tb" style="height:64px"></div><div class="sp" style="height:40px"></div></div>
<!-- /wp:wdl/lw-space-1 -->
<!-- wp:wdl/lw-pr-custom-title-12 {"mainTitle":"入って2年目の社員から","subTitle":"VOICE","headingLevel":2,"colorMain":"#1d4e89","colorSub":"#0f2a4a","colorMainText":"#ffffff","colorSubText":"#cddcef"} -->
