<h3 class="has-text-align-center has-text-color" style="color:#0f2a4a;font-size:24px;line-height:1.6;margin-top:0px;margin-bottom:16px">先に言っておきます</h3>
<!-- /wp:heading -->
<!-- wp:paragraph {"style":{"color":{"text":"#333b45"},"typography":{"fontSize":"16px","lineHeight":"1.9"}},"align":"center"} -->
<p class="has-text-align-center has-text-color" style="color:#333b45;font-size:16px;line-height:1.9">ここを知らずに入って、辞めてしまう人がいちばん多いので、先に書いておきます。</p>
<!-- /wp:paragraph -->
<!-- wp:wdl/lw-space-1 {"pcHeight":24,"tbHeight":20,"spHeight":16} -->
